pub async fn get_next_port(&self) -> Option<u16> {
    let ports = self.active_ports.read().await;
    if ports.is_empty() {
        None
    } else {
        let idx = self.counter.fetch_add(1, Ordering::Relaxed) % ports.len();
        Some(ports[idx])
    }
}

